#!/usr/bin/env python3
# Generate minimal probe .flf fonts.
import sys

def mkfont(path, hardblank='$', height=1, baseline=1, maxlen=8,
           oldlayout=-1, comments=1, printdir=0, fulllayout=None, codetagcount=None,
           glyphs=None, endmark='@'):
    # glyphs: dict code -> list of row strings (without endmarks)
    g = glyphs or {}
    lines = []
    header = f"flf2a{hardblank} {height} {baseline} {maxlen} {oldlayout} {comments}"
    if printdir is not None:
        header += f" {printdir}"
    if fulllayout is not None:
        header += f" {fulllayout}"
    if codetagcount is not None:
        header += f" {codetagcount}"
    lines.append(header)
    for i in range(comments):
        lines.append(f"comment {i}")
    for code in range(32, 127):
        rows = g.get(code, None)
        if rows is None:
            # default: the char itself twice, height rows
            ch = chr(code) if chr(code) not in (endmark,) else 'x'
            rows = [ch * 2] * height
        assert len(rows) == height
        for i, r in enumerate(rows):
            lines.append(r + endmark * (2 if i == height - 1 else 1))
    with open(path, 'w') as f:
        f.write('\n'.join(lines) + '\n')

if __name__ == '__main__':
    # probe font: each glyph is the char doubled, height 1
    mkfont('probe.flf', oldlayout=-1, comments=0)

